// Typed subscriptions to backend events. Payload types come from src/bindings/ (generated by ts-rs). The
// event names must match src-tauri/src/events.rs, which has a test pinning them.
import { isTauri } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import type { JobDone } from "@/bindings/JobDone";
import type { JobProgress } from "@/bindings/JobProgress";

export const JOB_PROGRESS_EVENT = "job:progress";
export const JOB_DONE_EVENT = "job:done";

const nothingToUnsubscribe: UnlistenFn = () => {};

/** Progress of a background job. Throttled by the backend, so it is safe to render on every event. */
export async function onJobProgress(handler: (progress: JobProgress) => void): Promise<UnlistenFn> {
  // In a plain browser (`pnpm dev`) there is no backend that could send events.
  if (!isTauri()) return nothingToUnsubscribe;
  return listen<JobProgress>(JOB_PROGRESS_EVENT, (event) => {
    handler(event.payload);
  });
}

/** A job finished: succeeded, failed or cancelled (`error.code === "CANCELLED"`). */
export async function onJobDone(handler: (done: JobDone) => void): Promise<UnlistenFn> {
  if (!isTauri()) return nothingToUnsubscribe;
  return listen<JobDone>(JOB_DONE_EVENT, (event) => {
    handler(event.payload);
  });
}
